package br.com.admeclesial.application.matrimonio; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.domain.matrimonio.*; import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.domain.pessoa.Pessoa; import br.com.admeclesial.infrastructure.persistence.matrimonio.ProcessoMatrimonialRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.time.LocalDate; import java.util.*; @Service public class ProcessoMatrimonialApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final ProcessoMatrimonialRepository repo; final OrganizacaoEclesialRepository orgRepo; final PessoaRepository pessoaRepo; public ProcessoMatrimonialApplicationService(ProcessoMatrimonialRepository r,OrganizacaoEclesialRepository o,PessoaRepository p){repo=r;orgRepo=o;pessoaRepo=p;} @Transactional public ProcessoMatrimonialResponse criar(ProcessoMatrimonialRequest r){return salvar(null,r);} @Transactional public ProcessoMatrimonialResponse atualizar(UUID u,ProcessoMatrimonialRequest r){return salvar(repo.findByUuid(u).orElseThrow(()->new IllegalArgumentException("Processo matrimonial não encontrado.")),r);} private ProcessoMatrimonialResponse salvar(ProcessoMatrimonial e,ProcessoMatrimonialRequest r){if(e!=null)validar(e.getOrganizacao().getUuid());validar(r.organizacaoEclesialUuid());OrganizacaoEclesial o=orgRepo.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização eclesial não encontrada.")); Pessoa p1=pessoaRepo.findByUuid(r.nubente1Uuid()).orElseThrow(()->new IllegalArgumentException("Nubente 1 não encontrado.")); Pessoa p2=pessoaRepo.findByUuid(r.nubente2Uuid()).orElseThrow(()->new IllegalArgumentException("Nubente 2 não encontrado.")); if(!o.isAtivo()||!p1.isAtivo()||!p2.isAtivo())throw new IllegalArgumentException("Organização e nubentes devem estar ativos."); if(p1.getUuid()!=null && p1.getUuid().equals(p2.getUuid()))throw new IllegalArgumentException("Os nubentes devem ser pessoas diferentes."); if(r.dataEncerramento()!=null&&r.dataEncerramento().isBefore(r.dataAbertura()))throw new IllegalArgumentException("Data de encerramento inválida."); if(e!=null && r.status()!=null && !transicaoPermitida(e.getStatus(),r.status()))throw new IllegalArgumentException("Transição de status do processo matrimonial não permitida."); if(e==null)e=new ProcessoMatrimonial(); e.setOrganizacao(o);e.setNubente1(p1);e.setNubente2(p2);e.setDataAbertura(r.dataAbertura());e.setDataEncerramento(r.dataEncerramento());e.setStatus(r.status()==null?StatusProcessoMatrimonial.ABERTO:r.status());e.setObservacao(StringUtils.hasText(r.observacao())?r.observacao().trim():null); return out(repo.save(e));} @Transactional(readOnly=true) public ProcessoMatrimonialResponse buscar(UUID u){var e=repo.findByUuid(u).orElseThrow(()->new IllegalArgumentException("Processo matrimonial não encontrado."));validar(e.getOrganizacao().getUuid());return out(e);} @Transactional(readOnly=true) public List<ProcessoMatrimonialResponse> listar(){var a=seguranca==null?null:seguranca.organizacoesAutorizadas();return repo.findAllByOrderByDataAberturaDesc().stream().filter(e->a==null||a.contains(e.getOrganizacao().getUuid())).map(this::out).toList();} private boolean transicaoPermitida(StatusProcessoMatrimonial atual, StatusProcessoMatrimonial novo){ if(atual==novo)return true; return switch(atual){case ABERTO -> novo==StatusProcessoMatrimonial.EM_ANALISE || novo==StatusProcessoMatrimonial.CANCELADO; case EM_ANALISE -> novo==StatusProcessoMatrimonial.CONCLUIDO || novo==StatusProcessoMatrimonial.CANCELADO; case CONCLUIDO, CANCELADO -> false;}; } private ProcessoMatrimonialResponse out(ProcessoMatrimonial e){return new ProcessoMatrimonialResponse(e.getUuid(),e.getOrganizacao().getUuid(),e.getOrganizacao().getNome(),e.getNubente1().getUuid(),e.getNubente1().getNome(),e.getNubente2().getUuid(),e.getNubente2().getNome(),e.getDataAbertura(),e.getDataEncerramento(),e.getStatus(),e.getObservacao());} private void validar(UUID u){if(seguranca!=null)seguranca.validarAcesso(u);}}